 */
function setCloseModal(onClose: () => void) {
    if (!modalStack.some(modal => modal.onClose === onClose)) {
        modalStack.push({onClose, isReady: false});
    }
    return () => {
        const index = modalStack.findIndex(modal => modal.onClose === onClose);
        if (index === -1) {
            return;
        }
        modalStack.splice(index, 1);
    };
}

function onModalReady() {
    if (modalStack.length === 0) {
        return;
    }
    const topMostModal = modalStack[modalStack.length - 1];
    topMostModal.isReady = true;
}

/**
 * Close topmost modal
 */
function closeTop() {
    if (modalStack.length === 0) {
        return;
    }

    const topMostModal = modalStack[modalStack.length - 1];

    if (!topMostModal.isReady) {
        return;
    }

    if (onModalClose) {
        topMostModal.onClose(isNavigate);
        modalStack.pop();
        return;
    }
    topMostModal.onClose();

